data_use = re.compile(r'skb(?:->|\.)data|->data\[|skb->data\[')

results = []
for root in roots:
    for dirpath, dirs, files in os.walk(root):
        for fn in files:
            if not fn.endswith('.c'):
                continue
            path = os.path.join(dirpath, fn)
            rel = os.path.relpath(path, S)
            if rel == 'net/phonet/pep.c':
                continue
            try:
                lines = open(path, errors='replace').read().split('\n')
            except Exception:
                continue
            for i, line in enumerate(lines):
                m = pull_call.search(line)
                if not m:
                    continue
                func = m.group(1)
                # determine if call is unchecked: look at this line and previous 3 for decision context
                ctx = "".join(lines[max(0,i-3):i+1])
                checked = bool(re.search(r'(if|while|return|[=!<>]=?|&&|\|\||else)\s*[^;]*$', line)) and re.search(r'if\s*\(|while\s*\(|return\s+[!A-Za-z_]|=\s*[^=]|\bif\b|&&|\|\|', line)
                # simpler: is the call inside an if/while condition or is its result assigned/compared?
                stripped = line.strip()
                if (re.match(r'if\s*\(\s*!?\s*(pskb_may_pull|pskb_may_pull_reason|pskb_pull|__skb_pull|skb_pull)', stripped) or
                    re.match(r'while\s*\(', stripped) or
                    re.search(r'=\s*' + func + r'\s*\(', line) or
                    re.search(r'if\s*\([^)]*' + func, line) or
                    re.match(r'return\s+' + func, stripped)):
                    checked = True
                else:
                    checked = False
                if func in ('pskb_may_pull','pskb_may_pull_reason','pskb_pull'):
                    if not checked:
                        results.append(('UNCHECKED_PULL', rel, i+1, stripped))
                else:
                    # skb_pull/__skb_pull: linearizer shape -> subsequent data reads with only len checks
                    nxt = "".join(lines[i+1:i+9])
                    if data_use.search(nxt):
                        prev = "".join(lines[max(0,i-10):i])
                        has_may_pull = 'pskb_may_pull' in prev or 'pskb_pull' in prev
                        has_len_check = re.search(r'skb->len\s*[<>=]|skb->len\s*==|len\s*[<>]', prev)
                        if not has_may_pull and has_len_check:
                            results.append(('PULL_AS_LINEARIZER', rel, i+1, stripped))
for r in results:
    print("\t".join(map(str, r)))
print("TOTAL", len(results), file=sys.stderr)
EOF
